import {MAX_WIND,WIND_BANDS,windResponse,WIND_MODEL_VERSION} from './wind-model.mjs?v=windbands1';
export function initWindSelection(){
 const input=document.querySelector('#env-wind'),grid=input.closest('.input-grid'),section=document.createElement('section'),key='harbor-twin.manual-wind.v1';section.className='wind-selection';
 section.innerHTML=`<div class="wind-selection-heading"><h3>풍속 선택</h3><output id="wind-selection-value" aria-live="polite"></output></div><label for="wind-slider">선택 바 · 0–${MAX_WIND} m/s</label><input id="wind-slider" type="range" min="0" max="${MAX_WIND}" step=".1" aria-label="풍속 선택 바"><div class="wind-scale"><span>0</span><span>30</span><span>60</span><span>90</span><span>${MAX_WIND}</span></div><p id="wind-selection-preview"></p><details open class="wind-range-table"><summary>구간별 연출 범위 · 표에서 선택</summary><div class="table-scroll"><table><thead><tr><th>연출 구간 / 풍속(m/s)</th><th>바람 추가 진폭</th><th>선택</th></tr></thead><tbody>${WIND_BANDS.map(b=>`<tr data-wind-band="${b.id}"><td><strong>${b.label}</strong><small>${b.min}–${b.max}${b.max===MAX_WIND?' 이하':' 미만'} m/s</small><small>${b.description}</small></td><td>${Number(b.wave[0].toFixed(3))}–${Number(b.wave[1].toFixed(3))}m</td><td><button type="button" data-wind-preset="${b.preset}" aria-label="${b.label} ${b.preset}m/s 선택">${b.preset}m/s</button></td></tr>`).join('')}</tbody></table></div></details><p class="wind-selection-help">표의 범위는 저장된 가정 모델 설정이며 기상특보 등급이 아닙니다. 관측 파고·주기는 보존하고 추가 바람 물결로 배와 수면을 함께 움직입니다. 상한은 3초 돌풍 기록을 참고한 실험 한도입니다.</p><p id="wind-save-status" role="status">선택 후 사용자 조건 적용 · 초기화를 누르면 실험에 반영됩니다.</p>`;
 input.min='0';input.max=String(MAX_WIND);input.step='.1';grid.before(section);const slider=section.querySelector('#wind-slider'),value=section.querySelector('#wind-selection-value'),preview=section.querySelector('#wind-selection-preview'),status=section.querySelector('#wind-save-status');
 function valid(){return input.value.trim()!==''&&Number.isFinite(Number(input.value))&&Number(input.value)>=0&&Number(input.value)<=MAX_WIND;}
 function sync(){if(!valid()){value.textContent='허용 범위 밖';preview.textContent='0–113.2m/s 안에서 선택하세요. 이전 적용 조건은 유지됩니다.';slider.disabled=false;return;}const wind=Number(input.value),r=windResponse(wind);slider.value=String(wind);value.textContent=`${wind.toFixed(1)} m/s · ${(wind*3.6).toFixed(1)} km/h`;preview.textContent=`${r.label} · 바람 추가 진폭 ${r.waveAmplitude.toFixed(2)}m (연출) · 선택만으로 적용되지 않습니다.`;for(const row of section.querySelectorAll('[data-wind-band]')){const active=row.dataset.windBand===r.bandId;row.classList.toggle('active',active);row.querySelector('button').setAttribute('aria-pressed',String(active));}}
 function select(wind){input.value=String(wind);input.dispatchEvent(new Event('input',{bubbles:true}));}
 slider.addEventListener('input',()=>select(slider.value));for(const b of section.querySelectorAll('[data-wind-preset]'))b.onclick=()=>select(b.dataset.windPreset);
 input.addEventListener('input',()=>{sync();if(valid()&&document.body.dataset.environmentMode==='manual'){try{localStorage.setItem(key,JSON.stringify({version:WIND_MODEL_VERSION,wind:Number(input.value)}));status.textContent='사용자 풍속 저장됨 · 적용 버튼을 눌러야 실험에 반영됩니다.';}catch{status.textContent='풍속은 선택됐지만 브라우저 저장을 사용할 수 없습니다. 적용 버튼으로 반영하세요.';}}});
 try{const saved=JSON.parse(localStorage.getItem(key)??'null');if(saved?.version===WIND_MODEL_VERSION&&typeof saved.wind==='number'&&Number.isFinite(saved.wind)&&saved.wind>=0&&saved.wind<=MAX_WIND){input.value=String(saved.wind);status.textContent='마지막 사용자 풍속 복원됨 · 실제 관측·실험에는 자동 적용하지 않습니다.';}}catch{}
 sync();
}
